				"branch", batch.Plan.TargetRef.String(),
				"previous_bytes_per_object", calibratedBytesPerObject,
				"observed_bytes_per_object", updated,
				"sent_bytes", sentBytes,
				"calibration_denom", calibrationDenom,
				"object_count", packObjectCount,
